      "kckckck.....",
      "kckckck.k...",
      "kccccckck...",
      "kcccccck....",
      "kccccck.....",
      ".kccck......",
      ".kSSSk......",
      ".kSSSk......",
      ".kkkkk......",
      "............"
    ],
    "qchair": [
      "...kkkkkk...",
      "...kWwwWk...",
      "...kWwwWk...",
      "...kWwwWk...",
      "...kWwwWk...",
      "..kkkkkkkk..",
      "..kRRRRRRk..",
      "..kkkkkkkk..",
      "..kw....wk..",
      "..kw....wk..",
      "..kw....wk..",
      "..kk....kk.."
    ],
    "qteacup": [
      "....k..k....",
      "...k..k.....",
      "....k..k....",
